/**
 * Loader for 3D Gaussian Splatting files (.ply, .splat, .splats, and .sog formats).
 *
 * Supports:
 * - PLY format (standard 3DGS training output with positions, scales, rotations, colors, SH coefficients)
 * - SPLAT/SPLATS format (web-optimized packed format)
 * - SOG format (PlayCanvas compressed WebP-based format, ~15-20x smaller than PLY)
 *
 * **Usage**
 * ```js
 * import { GaussianSplatsLoader } from '@three-blocks/core';
 *
 * const loader = new GaussianSplatsLoader();
 *
 * // Callback style
 * loader.load('/models/scene.ply', (splats) => {
 *   scene.add(splats);
 * });
 *
 * // Async style
 * const splats = await loader.loadAsync('/models/scene.ply');
 * scene.add(splats);
 *
 * // Load compressed SOG format
 * const splats = await loader.loadAsync('/models/scene.sog');
 * scene.add(splats);
 *
 * // With options
 * const splats = await loader.loadAsync('/models/scene.ply', undefined, {
 *   maxSplats: 2000000,
 *   enableSH: true,
 *   shDegree: 2,
 * });
 * ```
 *
 * @class GaussianSplatsLoader
 * @extends Loader
 * @short Loader for PLY, SPLAT, SPLATS, and SOG Gaussian Splatting files, returns a GaussianSplats object.
 * @category Loaders
 * @tags WebGPU
 */
export class GaussianSplatsLoader {
    /**
     * Create a GaussianSplatsLoader.
     *
     * @param {THREE.LoadingManager} [manager] Loading manager.
     */
    constructor(manager?: THREE.LoadingManager);
    /** Default options for created GaussianSplats instances. @type {Object} */
    defaultOptions: any;
    /**
     * Load a Gaussian Splatting file.
     *
     * @param {string} url URL to the .ply or .splat file.
     * @param {Function} [onLoad] Callback fired with the loaded GaussianSplats.
     * @param {Function} [onProgress] Progress callback.
     * @param {Function} [onError] Error callback.
     * @param {Object} [options] Options for the GaussianSplats instance.
     */
    load(url: string, onLoad?: Function, onProgress?: Function, onError?: Function, options?: any): void;
    /**
     * Load a Gaussian Splatting file asynchronously.
     *
     * @param {string} url URL to the .ply or .splat file.
     * @param {Function} [onProgress] Progress callback.
     * @param {Object} [options] Options for the GaussianSplats instance.
     * @returns {Promise<GaussianSplats>} Promise resolving to the loaded GaussianSplats.
     */
    loadAsync(url: string, onProgress?: Function, options?: any): Promise<GaussianSplats>;
    /**
     * Parse a buffer into a GaussianSplats instance.
     * For SOG files, use parseAsync() instead as they require async image decoding.
     *
     * @param {ArrayBuffer} buffer File data.
     * @param {string} url Original URL (for format detection).
     * @param {Object} [options] Options for the GaussianSplats instance.
     * @returns {GaussianSplats|Promise<GaussianSplats>} The parsed GaussianSplats instance (Promise for SOG).
     */
    parse(buffer: ArrayBuffer, url: string, options?: any): GaussianSplats | Promise<GaussianSplats>;
    /**
     * Parse a buffer into a GaussianSplats instance (async version).
     * Required for SOG files which need async image decoding.
     *
     * @param {ArrayBuffer} buffer File data.
     * @param {string} url Original URL (for format detection).
     * @param {Object} [options] Options for the GaussianSplats instance.
     * @returns {Promise<GaussianSplats>} Promise resolving to the parsed GaussianSplats instance.
     */
    parseAsync(buffer: ArrayBuffer, url: string, options?: any): Promise<GaussianSplats>;
    /**
     * Parse PLY format.
     * @private
     * @param {ArrayBuffer} buffer
     * @param {number} maxSplats Maximum splats to load.
     * @returns {Object} Parsed data.
     */
    private _parsePLY;
    /**
     * Detect SH degree from property names.
     * @private
     * @param {Object} propIndex Property name to index map.
     * @returns {number} SH degree (0-3).
     */
    private _detectSHDegree;
    /**
     * Parse SPLAT format (packed binary).
     * Standard format used by antimatter15/splat, SuperSplat, etc.
     * @private
     * @param {ArrayBuffer} buffer
     * @param {number} maxSplats Maximum splats to load.
     * @returns {Object} Parsed data.
     */
    private _parseSPLAT;
    /**
     * Parse compressed PLY format with per-chunk bounds (PlayCanvas/SuperSplat format).
     *
     * Data layout (SEQUENTIAL, not interleaved):
     * 1. ALL chunk headers (72 bytes each × numChunks)
     * 2. ALL vertex data (16 bytes each × numVertices)
     * 3. ALL SH data (optional, N bytes each × numVertices)
     *
     * @private
     * @param {ArrayBuffer} buffer
     * @param {number} numChunks Number of chunks (from "element chunk N")
     * @param {number} vertexCount Number of vertices (from "element vertex N")
     * @param {number} shElementCount Number of SH elements (from "element sh N")
     * @param {Array} chunkProperties Properties for chunk element
     * @param {Array} vertexProperties Properties for vertex element
     * @param {Array} shProperties Properties for SH element
     * @param {number} dataOffset Byte offset where binary data starts
     * @param {boolean} isLittleEndian Endianness
     * @param {number} maxSplats Maximum splats to load
     * @returns {Object} Parsed data.
     */
    private _parseCompressedPLYWithBounds;
    /**
     * Parse SOG format (PlayCanvas compressed WebP-based format).
     * SOG files are ZIP archives containing meta.json and WebP images.
     * Achieves ~15-20x compression compared to PLY.
     *
     * @private
     * @param {ArrayBuffer} buffer ZIP archive data.
     * @param {number} maxSplats Maximum splats to load.
     * @returns {Promise<Object>} Parsed data.
     */
    private _parseSOG;
    /**
     * Decode WebP images from SOG archive.
     * @private
     * @param {Object} files Unzipped file contents.
     * @param {Object} meta SOG metadata.
     * @returns {Promise<Object>} Decoded image data.
     */
    private _decodeSOGImages;
    /**
     * Dequantize SOG image data into splat arrays.
     * @private
     * @param {Object} images Decoded image data.
     * @param {Object} meta SOG metadata.
     * @param {number} count Number of splats to process.
     * @param {number} version SOG format version (1 or 2).
     * @returns {Object} Parsed data arrays.
     */
    private _dequantizeSOGData;
    /**
     * Parse spherical harmonics coefficients from SOG label/centroid images.
     * @private
     * @param {Object} labelsImg Labels image data.
     * @param {Object} centroidsImg Centroids image data.
     * @param {Object} meta SOG metadata.
     * @param {number} count Number of splats.
     * @param {number} imgWidth Image width for pixel indexing.
     * @returns {Object} SH coefficients and degree.
     */
    private _parseSOGSphericalHarmonics;
}
import { GaussianSplats } from './GaussianSplats.js';
